// Verify the new pro-editor studio: ribbon, gizmos, explorer, snap, undo, collab.
const { chromium } = require('/home/lane/rblx/node_modules/playwright');
const BASE = 'http://localhost:3001';

let pass = 0, fail = 0;
const ok = (name, cond) => { cond ? pass++ : fail++; console.log(`  ${cond ? '✅' : '❌'} ${name}`); };

async function signup(page, username) {
  await page.goto(BASE);
  await page.click('#tab-register');
  await page.fill('#auth-user', username);
  await page.fill('#auth-pass', 'test1234');
  await page.click('#auth-go');
  await page.waitForSelector('.hero', { timeout: 10000 });
}

async function partsOf(gid, page) {
  const cookie = (await page.context().cookies()).map((c) => `${c.name}=${c.value}`).join('; ');
  const r = await (await fetch(`${BASE}/api/games/${gid}`, { headers: { cookie } })).json();
  return r.game;
}

(async () => {
  const sfx = Math.random().toString(36).slice(2, 6);
  const browser = await chromium.launch({ headless: true, executablePath: '/usr/bin/google-chrome',
    args: ['--enable-unsafe-swiftshader'] });
  const ctxA = await browser.newContext({ viewport: { width: 1440, height: 860 } });
  const A = await ctxA.newPage();
  const errors = [];
  A.on('pageerror', (e) => errors.push('pageerror: ' + e.message));
  A.on('console', (m) => { if (m.type() === 'error') errors.push('console: ' + m.text()); });

  await signup(A, 'ed_' + sfx);
  await A.goto(BASE + '/#/studio');
  await A.waitForSelector('#new-name');
  await A.fill('#new-name', 'Gizmo World');
  await A.click('#new-go');
  await A.waitForSelector('#studio-canvas-wrap canvas');
  await A.waitForSelector('#st-config #cfg-name');
  const gid = A.url().match(/studio\/([\w-]+)/)[1];
  await A.waitForTimeout(800);

  // ---- layout pieces present ----
  ok('ribbon with 4 tool buttons', await A.locator('#studio-ribbon [data-tool]').count() === 4);
  ok('toolbox palette (12 part types)', await A.locator('#st-palette .tool-btn').count() === 12);
  ok('explorer lists baseplate + spawn', await A.locator('#st-explorer .exp-row').count() === 2);
  ok('status bar shows part count', (await A.locator('#sts-parts').textContent()) === '2 parts');

  // ---- place a block via toolbox ----
  await A.click('#st-palette button:has-text("Block")');
  await A.mouse.move(700, 430);
  await A.waitForTimeout(250);
  await A.mouse.click(700, 430);
  await A.waitForTimeout(500);
  let g = await partsOf(gid, A);
  ok('block placed (3 parts)', g.partCount === 3);
  ok('explorer updated to 3 rows', await A.locator('#st-explorer .exp-row').count() === 3);

  // ---- select via explorer click ----
  await A.keyboard.press('Escape'); // leave place tool
  const blockRow = A.locator('#st-explorer .exp-row:has-text("Block")').first();
  await blockRow.click();
  await A.waitForTimeout(200);
  ok('explorer click selects (props panel shows position)', await A.locator('#st-props input[data-prop="x"]').count() === 1);
  ok('ribbon selection group shows part', (await A.locator('#rb-sel-info').textContent()).includes('Block'));
  const selBefore = await A.locator('#st-props input[data-prop="x"]').inputValue();

  // ---- move gizmo drag along X ----
  await A.click('button[data-tool="move"]');
  await A.waitForTimeout(300);
  // gizmo sits at part center; project: find canvas center of selected part via evaluate is complex —
  // instead drag from a point slightly right of screen center of the part. Use props x before/after.
  // The part is roughly mid-viewport; the +X arrow extends right-ish. Try a few start points.
  const xBefore = Number(selBefore);
  // double-click row to focus camera on the part for a predictable view
  await blockRow.dblclick();
  await A.waitForTimeout(400);
  // After focus, part is centered. The X arrow (red) points along +x; from this camera angle it goes left-down.
  // Find the arrow on screen by probing pixels is overkill — drag using gizmo pick: mousedown on several candidate points until cursor turns 'grab'.
  const found = await A.evaluate(() => {
    // expose pick test: simulate mousemove over a grid and read cursor style set by hover feedback
    return null;
  });
  // brute-force probe: move mouse across a grid, find where cursor=grab
  let grabAt = null;
  for (let gx = 420; gx <= 1020 && !grabAt; gx += 30) {
    for (let gy = 280; gy <= 620 && !grabAt; gy += 25) {
      await A.mouse.move(gx, gy);
      await A.waitForTimeout(8);
      const cur = await A.evaluate(() => document.querySelector('#studio-canvas-wrap canvas').style.cursor);
      if (cur === 'grab') grabAt = { x: gx, y: gy };
    }
  }
  ok('gizmo handle hover detected (cursor=grab)', !!grabAt);
  if (grabAt) {
    await A.mouse.move(grabAt.x, grabAt.y);
    await A.mouse.down();
    await A.mouse.move(grabAt.x + 80, grabAt.y + 30, { steps: 10 });
    await A.mouse.up();
    await A.waitForTimeout(400);
    g = await partsOf(gid, A);
    const moved = g; // position changed server-side?
    const xAfter = Number(await A.locator('#st-props input[data-prop="x"]').inputValue().catch(() => 'NaN'));
    const posChanged = await A.evaluate(() => {
      const inp = document.querySelector('#st-props input[data-prop="x"]') || document.querySelector('#st-props input[data-prop="y"]') || document.querySelector('#st-props input[data-prop="z"]');
      return !!inp;
    });
    // check any coordinate changed vs before and is snapped to 0.5
    const vals = {};
    for (const k of ['x', 'y', 'z']) {
      vals[k] = Number(await A.locator(`#st-props input[data-prop="${k}"]`).inputValue());
    }
    const changed = vals.x !== xBefore || vals.y !== 0.5 || vals.z !== Number((await A.locator('#st-props input[data-prop="z"]').inputValue()));
    const snapped = Object.values(vals).every((v) => Math.abs(v * 2 - Math.round(v * 2)) < 1e-6);
    ok(`gizmo drag moved part (x:${xBefore}→${vals.x}, snapped=${snapped})`, vals.x !== xBefore && snapped);
  }

  // ---- scale gizmo ----
  await A.click('button[data-tool="scale"]');
  await A.waitForTimeout(300);
  const sxBefore = Number(await A.locator('#st-props input[data-prop="sx"]').inputValue());
  let grab2 = null;
  for (let gx = 420; gx <= 1020 && !grab2; gx += 30) {
    for (let gy = 280; gy <= 620 && !grab2; gy += 25) {
      await A.mouse.move(gx, gy);
      await A.waitForTimeout(8);
      const cur = await A.evaluate(() => document.querySelector('#studio-canvas-wrap canvas').style.cursor);
      if (cur === 'grab') grab2 = { x: gx, y: gy };
    }
  }
  ok('scale gizmo handle hover detected', !!grab2);
  if (grab2) {
    await A.mouse.move(grab2.x, grab2.y);
    await A.mouse.down();
    await A.mouse.move(grab2.x + 70, grab2.y - 20, { steps: 10 });
    await A.mouse.up();
    await A.waitForTimeout(400);
    const dims = {};
    for (const k of ['sx', 'sy', 'sz']) dims[k] = Number(await A.locator(`#st-props input[data-prop="${k}"]`).inputValue());
    const changed = dims.sx !== sxBefore || dims.sy !== 1 || dims.sz !== 4;
    ok(`scale drag resized part (sx:${sxBefore}→${dims.sx} sy:${dims.sy} sz:${dims.sz})`, changed);
  }

  // ---- undo restores ----
  await A.click('#rb-undo');
  await A.waitForTimeout(300);
  await A.click('#rb-undo');
  await A.waitForTimeout(300);
  g = await partsOf(gid, A);
  ok('undo x2 leaves 3 parts (geometry ops undone)', g.partCount === 3);

  // ---- duplicate ----
  await A.click('#rb-dup');
  await A.waitForTimeout(400);
  g = await partsOf(gid, A);
  ok('duplicate creates 4th part', g.partCount === 4);

  // ---- explorer filter ----
  await A.fill('#st-explorer-q', 'spawn');
  await A.waitForTimeout(250);
  ok('explorer filter narrows to spawn', await A.locator('#st-explorer .exp-row').count() === 1);
  await A.fill('#st-explorer-q', '');
  await A.waitForTimeout(250);

  // ---- snap off allows free values ----
  await A.click('#rb-snap-on');
  ok('snap toggle works (unchecked)', !(await A.isChecked('#rb-snap-on')));
  await A.click('#rb-snap-on');

  // ---- keyboard shortcuts ----
  await A.click('#studio-canvas-wrap canvas', { position: { x: 100, y: 100 } }); // deselect-ish click on empty space
  await A.keyboard.press('1');
  await A.waitForTimeout(150);
  const selectActive = await A.locator('[data-tool="select"].active').count();
  await A.keyboard.press('3');
  await A.waitForTimeout(150);
  const scaleActive = await A.locator('[data-tool="scale"].active').count();
  ok('keyboard 1/3 switch tools', selectActive === 1 && scaleActive === 1);

  // ---- collab still live with second editor ----
  const ctxB = await browser.newContext({ viewport: { width: 1280, height: 800 } });
  const B = await ctxB.newPage();
  B.on('pageerror', (e) => errors.push('B pageerror: ' + e.message));
  await signup(B, 'ed2_' + sfx);
  const cookieA = (await ctxA.cookies()).map((c) => `${c.name}=${c.value}`).join('; ');
  await fetch(`${BASE}/api/games/${gid}/collaborators`, {
    method: 'POST', headers: { 'Content-Type': 'application/json', cookie: cookieA },
    body: JSON.stringify({ username: 'ed2_' + sfx, action: 'add' }),
  });
  await B.goto(BASE + '/#/studio/' + gid);
  await B.waitForSelector('#studio-canvas-wrap canvas');
  await A.waitForSelector('#st-editors .editor-chip', { timeout: 8000 });
  ok('second editor chip appears', true);
  // B places a part; A's explorer updates live
  const beforeRows = await A.locator('#st-explorer .exp-row').count();
  await B.click('#st-palette button:has-text("Coin")');
  await B.mouse.move(640, 400);
  await B.waitForTimeout(250);
  await B.mouse.click(640, 400);
  await A.waitForFunction((n) => document.querySelectorAll('#st-explorer .exp-row').length === n + 1, beforeRows, { timeout: 6000 });
  ok('remote op updates explorer live', true);

  await A.screenshot({ path: '/tmp/glint-shots/s1-studio-pro.png' });
  await A.click('button[data-tool="move"]');
  const coinRow = A.locator('#st-explorer .exp-row:has-text("Coin")').first();
  await coinRow.dblclick();
  await A.waitForTimeout(600);
  await A.screenshot({ path: '/tmp/glint-shots/s2-studio-gizmo.png' });

  console.log('\nerrors: ' + (errors.length ? '\n' + errors.join('\n') : 'none'));
  await browser.close();
  console.log(`${pass} passed, ${fail} failed`);
  process.exit(fail || errors.length ? 1 : 0);
})().catch((e) => { console.error('TEST CRASH:', e.message); process.exit(1); });
